    'فایل پشتیبانِ این درخواست روی سرور در دسترس نیست: یا بارگذاری پذیرفته نشد (فایل خالی بود، ناقص رسید یا از حد مجاز این نصب بزرگ‌تر بود)، یا فایلی که پیش‌تر بارگذاری شده بود دیگر روی سرور پیدا نمی‌شود. فضای ذخیره‌سازی سرور و گزارش آن را بررسی کنید، سپس فایل را دوباره بارگذاری کنید. هیچ تغییری در این نصب داده نشد.',
  'web.recovery_code_archive_malformed':
    'این فایل را این نسخه از نکسا نمی‌تواند بخواند: یا فایل پشتیبان نکسا نیست یا ناقص است، یا با قالبی تازه‌تر از آنچه این نسخه می‌شناسد ساخته شده است. اگر فایل از نصبی با نسخه‌ی جدیدتر نکسا است، نسخه‌ای از نکسا را نصب کنید که این قالب را پشتیبانی می‌کند؛ وگرنه فایل پشتیبان سازگار دیگری انتخاب کنید. هیچ تغییری در این نصب داده نشد.',
  'web.recovery_code_checksum_mismatch':
    'فایل با کلید درست باز شد و رمزگشایی آن سالم بود، اما محتوای بازشده با چکیده‌ای که مشخصات خود فایل ثبت کرده یکی نیست؛ پس خود این فایل پشتیبان قابل اعتماد نیست (یا فایل روی سرور پس از راستی‌آزمایی عوض شده است) و بارگذاری دوباره‌ی همین فایل مشکل را حل نمی‌کند. فایل پشتیبان سالم دیگری را امتحان کنید و گزارش سرور را بررسی کنید. هیچ تغییری در این نصب داده نشد.',
  'web.recovery_code_manifest_invalid':
    'مشخصات داخل فایل پشتیبان خوانا نیست. فایل دیگری از همان سرور را امتحان کنید.',
  'web.recovery_code_restore_test_failed':
    'آزمون بازگردانی روی پایگاه‌داده‌ی آزمایشی موفق نشد. هیچ تغییری در این نصب داده نشد. فایل پشتیبان دیگری را امتحان کنید یا گزارش سرور را بررسی کنید.',
  'web.recovery_code_restored_database_empty':
    'فایل پشتیبان بازگردانده شد اما هیچ جدولی در آن نبود. این فایل برای بازیابی قابل استفاده نیست؛ فایل پشتیبان دیگری انتخاب کنید.',
  'web.recovery_code_migration_state_unreadable':
    'وضعیت نسخه‌ی پایگاه‌داده‌ی داخل فایل خوانا نیست. فایل پشتیبان دیگری را امتحان کنید.',
  'web.recovery_code_migration_incompatible':
    'وضعیت مهاجرت پایگاه‌داده‌ی داخل این فایل با این نسخه از نکسا قابل استفاده نیست: یا هیچ سابقه‌ی مهاجرتی ندارد، یا سابقه‌ی آن با مهاجرت‌های این نسخه جور نیست (واگرا)، یا از نسخه‌ی قدیمی‌تری است که این نسخه نتوانست آن را به‌روز کند. نسخه‌ی نکسایی را نصب کنید که با این فایل سازگار است، یا فایل پشتیبان دیگری انتخاب کنید؛ جزئیات در گزارش سرور است. هیچ تغییری در این نصب داده نشد.',
  'web.recovery_code_confirmation_invalid':
    'تأیید بازیابی نامعتبر، منقضی یا برای فایل دیگری بود. آزمون بازگردانی را دوباره انجام دهید و عبارت تأیید را از نو وارد کنید.',
  'web.recovery_code_emergency_backup_failed':
    'بکاپ اضطراری پیش از بازیابی کامل نشد، پس بازیابی آغاز نشد و نصب دست‌نخورده است. وضعیت بکاپ را بررسی کنید و دوباره تلاش کنید.',
  'web.recovery_code_emergency_backup_busy':
    'هنگام شروع، بکاپ دیگری در حال اجرا بود و بازیابی آغاز نشد. پس از پایان آن بکاپ، دوباره تلاش کنید.',
  'web.recovery_code_quiesce_failed':
    'توقف نوشتن‌ها برای بازیابی ممکن نشد، پس بازیابی انجام نشد و نصب به کار عادی ادامه می‌دهد. دوباره تلاش کنید.',
  'web.recovery_code_candidate_create_failed':
    'پایگاه‌داده‌ی موقت برای بازیابی ساخته نشد. نصب فعلی دست‌نخورده است. فضای دیسک و دسترسی پایگاه‌داده را بررسی کنید.',
  'web.recovery_code_candidate_restore_failed':
    'بازگردانی در پایگاه‌داده‌ی موقت شکست خورد. نصب فعلی دست‌نخورده است. گزارش سرور را بررسی کنید.',
  'web.recovery_code_candidate_validation_failed':
    'داده در پایگاه‌داده‌ی موقت بازگردانده شد، اما بررسی نهایی پیش از جایگزینی کامل نشد: یا بررسی آن اصلاً اجرا نشد (اتصال یا دسترسی پایگاه‌داده)، یا مهاجرت‌های این نسخه روی آن اجرا نشد، یا کلیدهای این نصب در آن نوشته نشد. نصب فعلی دست‌نخورده است و جایگزین نشد. اتصال و دسترسی‌های پایگاه‌داده و گزارش سرور را بررسی کنید و سپس دوباره تلاش کنید.',
  'web.recovery_code_cutover_failed':
    'جابه‌جایی پایگاه‌داده‌ها کامل نشد. پیش از هر اقدامی گزارش سرور و بخش «عملیات بازیابی» را بررسی کنید؛ پایگاه‌داده‌ی قبلی حذف نشده است.',
  'web.recovery_code_readiness_failed':
    'بازیابی انجام شد اما سامانه پس از آن آماده‌ی کار گزارش نشد. وضعیت سرویس‌ها را بررسی کنید؛ پایگاه‌داده‌ی قبلی برای بازگشت نگه داشته شده است.',
  'web.recovery_code_lease_expired':
    'پردازشگر بازیابی از کار ایستاد و کار متوقف شد. وضعیت سرویس بازیابی را بررسی کنید و در صورت نیاز از نو شروع کنید.',
  'web.recovery_code_internal':
    'خطای پیش‌بینی‌نشده رخ داد. جزئیات فقط در گزارش سرور ثبت شده است؛ آن را با همین کد بررسی کنید.',
  // A refused request on the recovery page, by its code; the server's English message is
