  'web.recovery_error_refused':
    'سرور این درخواست بازیابی را نپذیرفت. ممکن است تنظیمات سرور (مثلاً فعال بودن بارگذاری) پس از باز شدن این صفحه تغییر کرده باشد؛ صفحه را تازه کنید. اگر برای این درخواست ردیفی در بخش «عملیات بازیابی» ساخته شده باشد، علت در همان ردیف آمده است؛ وگرنه گزارش سرور را بررسی کنید.',
