  'web.payment_gateway_tetrapay_hint':
    'مبلغ‌ها در تتراپی به ریال ارسال می‌شود (تومان × 10). مشتری پس از پرداخت با لینک ربات برمی‌گردد و وضعیت را از خود پرداخت می‌بیند؛ بازگشت به‌تنهایی چیزی را تأیید نمی‌کند. پرداخت فقط پس از استعلام مستقیم (verify) با وضعیت «paid» و تطبیق شناسهٔ سفارش و مبلغ به ریال ثبت می‌شود. وب‌هوک اختیاری است و فقط استعلام را جلو می‌اندازد.',
