    'ساخت سرویس این سفارش هنوز به نتیجهٔ قطعی نرسیده است و بازپرداخت پولِ سرویسی که شاید ساخته شده باشد مجاز نیست. با پایان ساخت، این محدودیت خودبه‌خود برطرف می‌شود.',
